"""Synthetic-only full documents, generated by independent JDK. No codec import."""
import base64
import copy
import json
from pathlib import Path
import subprocess

ROOT=Path(__file__).resolve().parents[2]
SERVER_FIELDS=('ServerIP','ServerUser','ServerPass','ProxyIP','Cloud','Slowchave','Nameserver','V2RAY_URI','UDPServer','WireGuardConfig')
TWEAK_FIELDS=('Payload','CHost','SNI','DNSHost','V2RAY_JSON','V2RAY','V2RAY_SNI','V2RAY_URI')


def oracle(jobs):
    if not jobs:return []
    payload=''.join(op+'\t'+base64.b64encode(data).decode()+'\n' for op,data in jobs)
    p=subprocess.run(['java','-XX:-UsePerfData',str(ROOT/'tests/golden/creeb_vpn_oracle.java')],
                     input=payload,text=True,capture_output=True,check=True,timeout=60)
    return [base64.b64decode(line) for line in p.stdout.splitlines()]


def seal(doc):
    obj=copy.deepcopy(doc);jobs=[];locations=[]
    for section,fields in (('Servers',SERVER_FIELDS),('Tweaks',TWEAK_FIELDS)):
        for row in obj.get(section,[]):
            key='S' if section=='Servers' or 'Custom Tweak' not in row.get('pInfo','') else 'C'
            for field in fields:
                if isinstance(row.get(field),str):
                    jobs.append((key+'enc',row[field].encode()));locations.append((row,field))
    for (row,field),value in zip(locations,oracle(jobs)):row[field]=value.decode()
    raw=json.dumps(obj,ensure_ascii=False,separators=(',',':')).encode()
    return obj,oracle([('Cenc',raw)])[0]


def generate():
    server={'Name':'Synthetic — 😀','Flag':'rc','sInfo':'Custom Server','ServerPort':'22','UDPPort':'20000-50000:1:2',
            'extra':{'ServerPass':'unknown nested metadata'},**{k:k+' test α\r\n' for k in SERVER_FIELDS}}
    tweak={'Name':'Synthetic tweak','Flag':'rc','pInfo':'Custom Tweak','TunnelType':6,'CPort':'8080',
           'extra':{'SNI':'unknown nested metadata'},**{k:k+' test 😀\r\n' for k in TWEAK_FIELDS}}
    docs=[]
    basic={'Message':'plain notice','Servers':[server],'Tweaks':[tweak],'unmapped':['keep',None,0,False]}
    locked=copy.deepcopy(basic);locked['Security']={'PasswordProtect':True,'Password':'synthetic password',
        'DeviceIDLock':True,'DeviceID':'synthetic-id;second-id','Expiry':True,'ExpiryDate':1,'BlockRoot':True,
        'BlockPackages':True,'BlockedPackagesList':'example.invalid','MobileDataOnly':True,'PlayStoreOnly':True}
    mixed=copy.deepcopy(basic);stock=copy.deepcopy(tweak);stock['pInfo']='Bundled carrier';mixed['Tweaks'].append(stock)
    empty={'Tweaks':[{'pInfo':'Custom Tweak','Payload':'','SNI':None,'Name':'Only tweak'}]}
    cat=copy.deepcopy(mixed);cat.update({'Version':'synthetic-1','V2Json':'{"outbounds":[]}',
        'ServerBanner':'<b>synthetic</b>','isTimer':False,'TimeLimit':'0','AD_UNIT_OPEN':''})
    for name,obj in (('normal',basic),('locked',locked),('mixed-keys',mixed),('empty-optional',empty),('catalog',cat)):
        opened,cipher=seal(obj);docs.append({'name':name,'expected':obj,'outer':opened,'cipher':cipher.decode()})
    jobs=[(key+'enc',('A'*n+'α😀').encode()) for key in ('C','S') for n in range(12)]
    primitives=[{'key':op[0],'plainBase64':base64.b64encode(data).decode(),'cipher':out.decode()}
                for (op,data),out in zip(jobs,oracle(jobs))]
    return {'provenance':'Synthetic only; independently transcribed JDK XXTEA, two fixed keys',
            'documents':docs,'primitives':primitives}


if __name__=='__main__':print(json.dumps(generate(),ensure_ascii=False,indent=2))
